 with tempfile.TemporaryDirectory() as tmp:
  root=Path(tmp);mmmu=root/"mmmu-root"/"mmmu";mmmu.mkdir(parents=True);answers=root/"answers.json";predictions=root/"predictions.json";custody=root/"custody.json";score=root/"score.json";answers.write_text(json.dumps({"validation_math_1":{"question_type":"multiple-choice","ground_truth":"A"}}),encoding="utf-8");h=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();predictions.write_text(json.dumps({"schema_version":"ember-owned-predictions-v1","claim_status":"NON_ADMISSIBLE_RAW_PREDICTIONS","checkpoint_manifest_sha256":"a"*64,"model_config_sha256":"b"*64,"tokenizer_sha256":"c"*64,"inference_implementation_sha256":"d"*64,"benchmark":{"id":"MMMU","version":"v","capability":"image","split_sha256":h(answers),"protocol_sha256":"e"*64},"decoding":{"strategy":"GREEDY_AUTOREGRESSIVE","teacher_forcing":False,"max_new_tokens":1,"temperature":0,"top_p":1,"stop_token_ids":[2]},"rows":[{"id":"validation_math_1","input_sha256":"f"*64,"generated_token_ids":[2],"stop_reason":"eos","output":{"kind":"text","text":"A"}}]}),encoding="utf-8");custody.write_text(json.dumps({"benchmark_id":"MMMU","benchmark_version":"v","split":{"name":"validation","answer_dictionary_sha256":h(answers)}}));(mmmu/"main_eval_only.py").write_text("import argparse,json\np=argparse.ArgumentParser();p.add_argument('--output_path');p.add_argument('--answer_path');a=p.parse_args();assert json.load(open(a.output_path))=={'validation_math_1':'A'};print({'Overall':{'num':1,'acc':1.0}})\n",encoding="utf-8");r=subprocess.run([sys.executable,str(SCRIPT),"--mmmu-root",str(root/"mmmu-root"),"--answers",str(answers),"--canonical-predictions",str(predictions),"--frozen-mmmu-manifest",str(custody),"--score-output",str(score)],text=True,capture_output=True,check=False);assert r.returncode==0,r.stderr;assert json.loads(score.read_text(encoding="utf-8"))["sample_count"]==1